    Match name against pattern using fnmatch.fnmatchcase semantics.
    Supports *, ?, [seq], [!seq], with ] immediately after [ or [! being literal.
    Unterminated [ is treated as literal [.
    """
    def _match(pattern, name):
        # Convert pattern to a list of tokens for easier processing
        # We'll use a recursive/iterative approach with backtracking for *

        # First, parse the pattern into a list of matchers
        # Each matcher is a tuple:
        #   ('any',) for *
        #   ('one',) for ?
        #   ('class', [chars], negated) for [seq] or [!seq]
        #   ('literal', char) for other characters

        tokens = []
        i = 0
        n = len(pattern)

        while i < n:
            c = pattern[i]
            if c == '*':
                # Consecutive * can be collapsed, but let's just add one
                tokens.append(('any',))
                i += 1
            elif c == '?':
                tokens.append(('one',))
                i += 1
            elif c == '[':
                # Try to parse a character class
                # Check if this is a valid [seq] or [!seq]
                j = i + 1
                negated = False
                if j < n and pattern[j] == '!':
                    negated = True
                    j += 1

                # Check if ] is immediately after [ or [!
                if j < n and pattern[j] == ']':
                    # ] is literal, so [ is literal
                    tokens.append(('literal', '['))
                    i += 1
                    continue

                # Parse the character class until ]
                chars = []
                k = j
                found_close = False
                while k < n:
                    if pattern[k] == ']':
                        found_close = True
                        break
                    # Check for range
                    if (k + 2 < n and pattern[k+1] == '-' and pattern[k+2] != ']'):
                        # It's a range
                        start_c = pattern[k]
                        end_c = pattern[k+2]
                        # Add all chars in range
                        for code in range(ord(start_c), ord(end_c) + 1):
                            chars.append(chr(code))
                        k += 3
                    else:
                        chars.append(pattern[k])
                        k += 1

                if not found_close:
                    # Unterminated [, treat as literal [
                    tokens.append(('literal', '['))
                    i += 1
                    continue

                # Valid character class
                tokens.append(('class', chars, negated))
                i = k + 1  # Skip past the ]
            else:
                tokens.append(('literal', c))
                i += 1

        # Now match name against tokens
        # Use recursion with memoization or iterative with backtracking
        # Since * can match any length, we need backtracking

        def _match_tokens(tokens, ti, name, ni):
            if ti == len(tokens):
                return ni == len(name)

            token = tokens[ti]

            if token[0] == 'any':
                # * matches any number of characters (including zero)
                # Try matching zero or more characters
                for end in range(ni, len(name) + 1):
                    if _match_tokens(tokens, ti + 1, name, end):
                        return True
                return False
            elif token[0] == 'one':
                # ? matches exactly one character
                if ni < len(name):
                    return _match_tokens(tokens, ti + 1, name, ni + 1)
                return False
            elif token[0] == 'class':
                _, chars, negated = token
                if ni >= len(name):
                    return False
                ch = name[ni]
                in_class = ch in chars
                if negated:
                    matched = not in_class
                else:
                    matched = in_class
                if matched:
                    return _match_tokens(tokens, ti + 1, name, ni + 1)
                return False
            elif token[0] == 'literal':
                _, ch = token
                if ni < len(name) and name[ni] == ch:
                    return _match_tokens(tokens, ti + 1, name, ni + 1)
                return False

        return _match_tokens(tokens, 0, name, 0)

    return _match(pattern, name)
