      - [!seq] : negated character class
      - ] immediately after [ or [! is a literal ]
      - unterminated [ is a literal [
    Matching is anchored to the whole string.
    """

    def match_from(p_idx, n_idx):
        # Base case: both exhausted
        if p_idx == len(pattern) and n_idx == len(name):
            return True
        # Pattern exhausted but name not
        if p_idx == len(pattern):
            return False
        # Name exhausted but pattern not
        if n_idx == len(name):
            # Only possible if remaining pattern is all '*'
            while p_idx < len(pattern) and pattern[p_idx] == '*':
                p_idx += 1
            return p_idx == len(pattern)

        p_char = pattern[p_idx]

        if p_char == '*':
            # Consume consecutive '*'
            while p_idx < len(pattern) and pattern[p_idx] == '*':
                p_idx += 1
            # Now try to match pattern[p_idx:] against name[n_idx:]
            # '*' matches any run (including empty), so we try all possible splits
            # Try matching zero characters first, then one, two, etc.
            for k in range(n_idx, len(name) + 1):
                if match_from(p_idx, k):
                    return True
            return False

        elif p_char == '?':
            # Matches exactly one character
            return match_from(p_idx + 1, n_idx + 1)

        elif p_char == '[':
            # Check for negation
            negated = False
            start = p_idx + 1
            if start < len(pattern) and pattern[start] == '!':
                negated = True
                start += 1

            # A ] immediately after [ or [! is a literal ]
            # So we need to find the closing ] that is not the first char
            # Build the character class
            # We need to find the matching closing bracket
            # The first ] after [ or [! is literal, so we skip it if it's the first char in the class
            i = start
            # If i is at a ], it's literal, so we need to find the next ]
            # Actually, per spec: "A ] immediately after [ or [! is a literal"
            # So if pattern[i] == ']', we include it as a literal and continue looking for the closing ]

            # Parse the character class
            # We'll collect the set of characters in the class
            char_set = set()
            # First, check if the first character is a literal ]
            if i < len(pattern) and pattern[i] == ']':
                char_set.add(']')
                i += 1

            # Now find the closing ]
            closed = False
            while i < len(pattern):
                if pattern[i] == ']':
                    closed = True
                    break
                # Check for range
                if i + 2 < len(pattern) and pattern[i + 1] == '-' and pattern[i + 2] != ']':
                    # It's a range
                    low = pattern[i]
                    high = pattern[i + 2]
                    for c in range(ord(low), ord(high) + 1):
                        char_set.add(chr(c))
                    i += 3
                else:
                    char_set.add(pattern[i])
                    i += 1

            if not closed:
                # Unterminated [ is a literal [
                # So match '[' as a literal character
                if n_idx < len(name) and name[n_idx] == '[':
                    return match_from(p_idx + 1, n_idx + 1)
                else:
                    return False

            # Now check if the current character in name matches the class
            if n_idx >= len(name):
                return False
            n_char = name[n_idx]
            if negated:
                matched = n_char not in char_set
            else:
                matched = n_char in char_set

            if matched:
                return match_from(i + 1, n_idx + 1)
            else:
                return False

        else:
            # Literal character
            if n_idx < len(name) and name[n_idx] == p_char:
                return match_from(p_idx + 1, n_idx + 1)
            else:
                return False

    return match_from(0, 0)
